import React, { useState, useEffect } from 'react';
import chatBgImg from '../../assets/nen_khung_chat.jpg';

const QuanLyHoaDon = () => {
    const now = new Date();
    const currentMonth = now.getMonth() + 1;
    const currentYear = now.getFullYear();

    const [selectedMonth, setSelectedMonth] = useState(currentMonth);
    const [selectedYear, setSelectedYear] = useState(currentYear);
    const [viewRoom, setViewRoom] = useState(null);
    const [loading, setLoading] = useState(false);

    // 1. ĐẦU CHỜ BACKEND: Lưu danh sách trạng thái của tất cả phòng trong tháng đã chọn
    const [roomsStatus, setRoomsStatus] = useState({}); 
    // 2. ĐẦU CHỜ BACKEND: Lưu chi tiết hóa đơn của phòng đang được click
    const [roomDetail, setRoomDetail] = useState(null);

    const years = [2024, 2025, 2026];
    const months = Array.from({ length: 12 }, (_, i) => i + 1);

    const allRooms = [];
    for (let floor = 1; floor <= 9; floor++) {
        for (let num = 1; num <= 5; num++) {
            allRooms.push(`${floor}0${num}`);
        }
    }

    // --- LOGIC KẾT NỐI BACKEND (MÔ PHỎNG) ---
    useEffect(() => {
        const fetchMonthlyData = async () => {
            setLoading(true);
            // Sau này: const res = await axios.get(`/api/invoices?month=${selectedMonth}&year=${selectedYear}`);

            setTimeout(() => {
                const mockStatus = {};
                const isPast = selectedYear < currentYear || (selectedYear === currentYear && selectedMonth < currentMonth);

                allRooms.forEach(room => {
                    // Logic: Tháng cũ = 'paid' (Xanh), Tháng hiện tại = 'unpaid' (Vàng)
                    mockStatus[room] = isPast ? 'paid' : (selectedYear === currentYear && selectedMonth === currentMonth ? 'unpaid' : 'future');
                });

                setRoomsStatus(mockStatus);
                setLoading(false);
            }, 300);
        };
        fetchMonthlyData();
    }, [selectedMonth, selectedYear]);

    // Khi click chọn 1 phòng cụ thể
    useEffect(() => {
        if (!viewRoom) return;
        // Sau này: const res = await axios.get(`/api/invoices/${viewRoom}?month=${selectedMonth}...`);

        if (roomsStatus[viewRoom] === 'paid') {
            setRoomDetail({
                content: `Tiền phòng tháng ${selectedMonth}/${selectedYear}`,
                amount: 5000000,
                time: `01/${selectedMonth.toString().padStart(2, '0')}/${selectedYear}`,
                status: "ĐÃ THANH TOÁN"
            });
        } else {
            setRoomDetail(null);
        }
    }, [viewRoom, roomsStatus]);

    // Hàm trả về Style dựa trên trạng thái phòng từ Backend
    const getRoomStyle = (room) => {
        const status = roomsStatus[room];
        const isSelected = viewRoom === room;

        if (status === 'paid') return { bg: isSelected ? '#5a8d6b' : '#e6f4ea', color: '#1e7e34', border: '1px solid #c3e6cb' };
        if (status === 'unpaid') return { bg: isSelected ? '#d4ac0d' : '#ffcc00', color: '#333', border: '1px solid #e6b800' };
        return { bg: 'rgba(255,255,255,0.3)', color: '#999', border: '1px solid rgba(255,255,255,0.1)' };
    };

    return (
        <div style={{
            flex: 1, borderRadius: '30px', display: 'flex', flexDirection: 'column', 
            backgroundImage: `url(${chatBgImg})`, backgroundSize: 'cover',
            backgroundPosition: 'center', overflow: 'hidden', height: 'calc(100vh - 120px)'
        }} className="glass-card">

            {/* Header Selectors */}
            <div style={{ padding: '20px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', background: 'rgba(0,0,0,0.2)' }}>
                <h2 style={{ color: '#fff', margin: 0, fontSize: '22px' }}>QUẢN LÝ HÓA ĐƠN</h2>
                <div style={{ display: 'flex', gap: '10px' }}>
                    <select value={selectedMonth} onChange={(e) => setSelectedMonth(parseInt(e.target.value))} style={{ padding: '10px', borderRadius: '12px', border: 'none', fontWeight: 'bold' }}>
                        {months.map(m => <option key={m} value={m}>Tháng {m}</option>)}
                    </select>
                    <select value={selectedYear} onChange={(e) => setSelectedYear(parseInt(e.target.value))} style={{ padding: '10px', borderRadius: '12px', border: 'none', fontWeight: 'bold' }}>
                        {years.map(y => <option key={y} value={y}>Năm {y}</option>)}
                    </select>
                </div>
            </div>

            <div style={{ flex: 1, padding: '20px', display: 'flex', gap: '25px', overflow: 'hidden' }}>

                {/* CỘT TRÁI: DANH SÁCH PHÒNG (STATUS-BASED) */}
                <div className="custom-scrollbar" style={{ 
                    width: '220px', display: 'grid', gridTemplateColumns: 'repeat(5, 1fr)', 
                    gap: '8px', alignContent: 'flex-start', overflowY: 'auto',
                    padding: '15px', backgroundColor: 'rgba(0,0,0,0.3)', borderRadius: '20px'
                }}>
                    {allRooms.map(room => {
                        const style = getRoomStyle(room);
                        return (
                            <div key={room} onClick={() => setViewRoom(room)}
                                style={{ 
                                    background: style.bg, color: style.color, border: style.border,
                                    padding: '12px 0', borderRadius: '10px', textAlign: 'center', 
                                    fontSize: '12px', fontWeight: 'bold', cursor: 'pointer', transition: '0.2s',
                                    boxShadow: viewRoom === room ? '0 0 10px rgba(255,255,255,0.3)' : 'none'
                                }}>
                                {room}
                            </div>
                        );
                    })}
                </div>

                {/* CỘT PHẢI: CHI TIẾT HÓA ĐƠN */}
                <div style={{ 
                    flex: 1, backgroundColor: '#fff', borderRadius: '30px', 
                    padding: '40px', display: 'flex', flexDirection: 'column', color: '#333'
                }}>
                    {loading ? (
                        <div style={{ flex: 1, display: 'flex', justifyContent: 'center', alignItems: 'center', color: '#8b5e5e', fontWeight: 'bold' }}>
                            ĐANG TẢI DỮ LIỆU THÁNG {selectedMonth}...
                        </div>
                    ) : viewRoom ? (
                        roomDetail ? (
                            <div style={{ animation: 'fadeIn 0.3s' }}>
                                <div style={{ borderBottom: '3px solid #8b5e5e', paddingBottom: '20px', marginBottom: '30px' }}>
                                    <span style={{ fontSize: '18px', color: '#8b5e5e', fontWeight: 'bold' }}>CHI TIẾT PHÒNG</span>
                                    <h1 style={{ fontSize: '50px', margin: 0, fontWeight: '900' }}>{viewRoom}</h1>
                                </div>
                                <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
                                    <DetailRow label="Nội dung" value={roomDetail.content} />
                                    <DetailRow label="Số tiền" value={`${roomDetail.amount.toLocaleString()}đ`} color="#28a745" bold />
                                    <DetailRow label="Ngày thanh toán" value={roomDetail.time} />
                                    <div style={{ marginTop: '20px' }}>
                                        <span style={{ padding: '10px 20px', backgroundColor: '#e6f4ea', color: '#1e7e34', borderRadius: '12px', fontWeight: 'bold', fontSize: '14px' }}>
                                            ✅ {roomDetail.status}
                                        </span>
                                    </div>
                                </div>
                            </div>
                        ) : (
                            <div style={{ flex: 1, display: 'flex', flexDirection: 'column', justifyContent: 'center', alignItems: 'center', textAlign: 'center' }}>
                                <div style={{ fontSize: '80px', marginBottom: '20px' }}>🟡</div>
                                <h2 style={{ fontSize: '30px', color: '#d4ac0d' }}>CHƯA THANH TOÁN</h2>
                                <p style={{ color: '#777', fontSize: '18px' }}>Phòng {viewRoom} chưa hoàn tất đóng tiền tháng {selectedMonth}.</p>
                                <button style={{ marginTop: '20px', padding: '15px 30px', borderRadius: '15px', border: 'none', backgroundColor: '#8b5e5e', color: '#fff', fontWeight: 'bold', cursor: 'pointer' }}>
                                    Gửi thông báo nhắc nhở
                                </button>
                            </div>
                        )
                    ) : (
                        <div style={{ flex: 1, display: 'flex', justifyContent: 'center', alignItems: 'center', color: '#ccc', fontSize: '20px', fontStyle: 'italic' }}>
                            Vui lòng chọn một số phòng ở bên trái...
                        </div>
                    )}
                </div>
            </div>
            <style>{`
                .custom-scrollbar::-webkit-scrollbar { width: 6px; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.2); border-radius: 10px; }
                @keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
            `}</style>
        </div>
    );
};

const DetailRow = ({ label, value, color, bold }) => (
    <div style={{ display: 'flex', justifyContent: 'space-between', borderBottom: '1px solid #eee', paddingBottom: '15px' }}>
        <span style={{ fontSize: '18px', color: '#777' }}>{label}</span>
        <span style={{ fontSize: '20px', fontWeight: bold ? '900' : '600', color: color || '#333' }}>{value}</span>
    </div>
);

export default QuanLyHoaDon;
